def jcur(pid, path):
    for f in glob.glob(f'Products_json/Base_oils_json/*/EXXONMOBIL_{pid}/*.json'):
        v = json.load(open(f, encoding='utf-8'))['fields'].get(path)
        if isinstance(v, dict) and 'value' in v:
            return f"{v.get('value')} (qualifier '{v.get('qualifier')}', method '{v.get('method')}')"
    return 'not found'


